 function resize(){const r=canvas.getBoundingClientRect(),scale=Math.min(window.devicePixelRatio||1,1.6,1280/Math.max(1,r.width),1850/Math.max(1,r.height));canvas.width=Math.max(1,Math.round(r.width*scale));canvas.height=Math.max(1,Math.round(r.height*scale));gl.viewport(0,0,canvas.width,canvas.height);dirty=true;}new ResizeObserver(resize).observe(canvas);resize();
 renderer=(p,t,g)=>{const index=p<.5?0:1,f=clamp(p*2-index),batch=buffers[index];gl.clear(gl.COLOR_BUFFER_BIT);gl.bindBuffer(gl.ARRAY_BUFFER,batch.buffer);gl.vertexAttribPointer(pa,2,gl.FLOAT,false,16,0);gl.vertexAttribPointer(pb,2,gl.FLOAT,false,16,8);gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,textures[index]);gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,textures[index+1]);gl.uniform1f(ub,f);gl.uniform1f(ud,smooth((f-.18)/.64));gl.uniform1f(ut,t);gl.uniform1f(ug,g);gl.drawArrays(gl.TRIANGLES,0,batch.count);};
