 function resize(){const r=document.getElementById('characterCanvas').parentElement.getBoundingClientRect();const scale=Math.min(window.devicePixelRatio||1,1.5,700/Math.max(1,r.width));canvas.width=Math.max(1,Math.round(r.width*scale));canvas.height=Math.round(canvas.width*1664/1152);dirty=true;}new ResizeObserver(resize).observe(canvas.parentElement);resize();
